const subject = @import("subject");
pub export fn agent_observe(index: u32) u64 {
    return switch (index) { 0 => subject.maximumToolArgumentsByteLength(bool), 1 => subject.maximumToolArgumentsByteLength(u8), 2 => subject.maximumToolArgumentsByteLength(i8), 3 => subject.maximumToolArgumentsByteLength(u64), 4 => subject.maximumToolArgumentsByteLength(i64), else => 999 };
}
